messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            font-family: sans-serif;
            font-size: 16px;
            background: rgba(0,0,0,0.3);
            padding: 5px 10px;
            border-radius: 5px;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Humanoid Animation Cycle</div>
    <!-- Import Three.js as requested -->
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // Seconds
        const WALK_START = 2;
        const RUN_START = 5;
        const STAND_START = 8;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(-5, 3, 8); // Side-on view
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(-5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Materials ---
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xf0e6d2, flatShading: true });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0xe74c3c, flatShading: true });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x3498db, flatShading: true });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x2c3e50, flatShading: true });

        // --- Helper: Create Box with Pivot at Top ---
        function createLimb(w, h, d, material, x, y, z) {
            const group = new THREE.Group();
            group.position.set(x, y, z);

            const geo = new THREE.BoxGeometry(w, h, d);
            geo.translate(0, -h / 2, 0); // Move geometry down so pivot is at top
            const mesh = new THREE.Mesh(geo, material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            group.add(mesh);

            return group;
        }

        // --- Character Construction ---
        const character = new THREE.Group();
        scene.add(character);

        // 1. Hips (Root of motion)
        const hips = new THREE.Group();
        hips.position.set(0, 1.2, 0);
        character.add(hips);

        // 2. Torso
        const torso = new THREE.Group();
        torso.position.set(0, 0, 0); // Relative to hips
        hips.add(torso);

        const torsoGeo = new THREE.BoxGeometry(0.5, 0.7, 0.3);
        torsoGeo.translate(0, 0.35, 0); // Pivot at bottom center
        const torsoMesh = new THREE.Mesh(torsoGeo, shirtMat);
        torsoMesh.castShadow = true;
        torso.add(torsoMesh);

        // 3. Head
        const head = new THREE.Group();
        head.position.set(0, 0.7, 0); // Top of torso
        torso.add(head);

        const headGeo = new THREE.BoxGeometry(0.35, 0.4, 0.35);
        headGeo.translate(0, 0.2, 0);
        const headMesh = new THREE.Mesh(headGeo, skinMat);
        headMesh.castShadow = true;
        head.add(headMesh);

        // 4. Arms (Shoulders)
        // Left Arm
        const leftShoulder = new THREE.Group();
        leftShoulder.position.set(0.3, 0.6, 0); // Shoulder height
        torso.add(leftShoulder);
        const leftArm = createLimb(0.15, 0.6, 0.15, skinMat, 0, 0, 0);
        leftShoulder.add(leftArm);

        // Right Arm
        const rightShoulder = new THREE.Group();
        rightShoulder.position.set(-0.3, 0.6, 0);
        torso.add(rightShoulder);
        const rightArm = createLimb(0.15, 0.6, 0.15, skinMat, 0, 0, 0);
        rightShoulder.add(rightArm);

        // 5. Legs (Hips)
        // Left Leg
        const leftHip = new THREE.Group();
        leftHip.position.set(0.15, -0.1, 0);
        hips.add(leftHip);
        const leftLeg = createLimb(0.2, 0.7, 0.2, pantsMat, 0, 0, 0);
        leftHip.add(leftLeg);

        // Left Foot
        const leftFoot = new THREE.Group();
        leftFoot.position.set(0, -0.7, 0);
        leftLeg.add(leftFoot);
        const leftFootGeo = new THREE.BoxGeometry(0.18, 0.1, 0.3);
        leftFootGeo.translate(0, -0.05, 0.1); // Pivot at heel-ish
        const leftFootMesh = new THREE.Mesh(leftFootGeo, shoeMat);
        leftFootMesh.castShadow = true;
        leftFoot.add(leftFootMesh);

        // Right Leg
        const rightHip = new THREE.Group();
        rightHip.position.set(-0.15, -0.1, 0);
        hips.add(rightHip);
        const rightLeg = createLimb(0.2, 0.7, 0.2, pantsMat, 0, 0, 0);
        rightHip.add(rightLeg);

        // Right Foot
        const rightFoot = new THREE.Group();
        rightFoot.position.set(0, -0.7, 0);
        rightLeg.add(rightFoot);
        const rightFootGeo = new THREE.BoxGeometry(0.18, 0.1, 0.3);
        rightFootGeo.translate(0, -0.05, 0.1);
        const rightFootMesh = new THREE.Mesh(rightFootGeo, shoeMat);
        rightFootMesh.castShadow = true;
        rightFoot.add(rightFootMesh);

        // --- Environment ---
        // Ground Plane (Treadmill belt)
        const groundGeo = new THREE.PlaneGeometry(100, 100);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, flatShading: true });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.01;
        ground.receiveShadow = true;
        scene.add(ground);

        // Treadmill Frame (Visuals)
        const frameMat = new THREE.MeshStandardMaterial({ color: 0x222222, flatShading: true });
        const leftSide = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.8, 2), frameMat);
        leftSide.position.set(-1.5, -0.4, 0);
        scene.add(leftSide);
        const rightSide = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.8, 2), frameMat);
        rightSide.position.set(1.5, -0.4, 0);
        scene.add(rightSide);

        // --- Animation Logic ---
        const clock = new THREE.Clock();

        // Helper function to calculate limb angles based on phase
        // phase: 0 to 2*PI representing one full stride
        function getLimbAngle(phase, amplitude) {
            return Math.sin(phase) * amplitude;
        }

        // Helper function to calculate foot rotation (toe up/down)
        function getFootAngle(phase, amplitude) {
            // Toe lifts when leg swings back (sin < 0 roughly)
            // Toe points down when leg swings forward
            return Math.sin(phase - Math.PI/2) * amplitude;
        }

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const cycleTime = time % CYCLE_DURATION;

            // Determine State
            let state = 'STAND';
            let progress = 0; // 0 to 1 for the current phase
            let speedMultiplier = 1;
            let lean = 0;
            let legSwing = 0;
            let armSwing = 0;
            let footSwing = 0;

            if (cycleTime < WALK_START) {
                state = 'STAND';
            } else if (cycleTime < RUN_START) {
                state = 'WALK';
                // 3 seconds duration
                const t = cycleTime - WALK_START;
                progress = t / 3;
                speedMultiplier = 1;
                legSwing = 0.6; // Radians
                armSwing = 0.5;
                footSwing = 0.3;
                lean = 0.1; // Slight forward lean
            } else if (cycleTime < STAND_START) {
                state = 'RUN';
                // 3 seconds duration
                const t = cycleTime - RUN_START;
                progress = t / 3;
                speedMultiplier = 2.5; // Faster
                legSwing = 1.0;
                armSwing = 0.8;
                footSwing = 0.5;
                lean = 0.35; // More lean
            } else {
                state = 'STAND';
            }

            // --- Apply Animations ---

            // 1. Body Lean
            // Smoothly transition lean? For simplicity, direct set or lerp
            // We'll just set it based on state for this cycle logic
            let targetLean = 0;
            if (state === 'WALK') targetLean = 0.15;
            if (state === 'RUN') targetLean = 0.4;

            // Simple Lerp for smooth transitions
            torso.rotation.x += (targetLean - torso.rotation.x) * 0.1;

            // 2. Limb Movement
            if (state === 'WALK' || state === 'RUN') {
                // Calculate phase based on progress and speed
                // 1 full stride cycle = 2*PI
                const phase = progress * Math.PI * 2 * speedMultiplier;

                // Legs (Out of phase: Left is 0, Right is PI)
                leftHip.rotation.x = getLimbAngle(phase, legSwing);
                rightHip.rotation.x = getLimbAngle(phase + Math.PI, legSwing);

                // Feet
                leftFoot.rotation.x = getFootAngle(phase, footSwing);
                rightFoot.rotation.x = getFootAngle(phase + Math.PI, footSwing);

                // Arms (Opposite to legs: Left arm moves with Right leg)
                leftShoulder.rotation.x = getLimbAngle(phase + Math.PI, armSwing);
                rightShoulder.rotation.x = getLimbAngle(phase, armSwing);
            } else {
                // Stand: Reset to 0
                leftHip.rotation.x *= 0.9;
                rightHip.rotation.x *= 0.9;
                leftShoulder.rotation.x *= 0.9;
                rightShoulder.rotation.x *= 0.9;
                leftFoot.rotation.x *= 0.9;
                rightFoot.rotation.x *= 0.9;
            }

            // Update UI
            const infoDiv = document.getElementById('info');
            infoDiv.innerText = `Time: ${time.toFixed(1)}s | State: ${state}`;

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();

    </script>
</body>
</html>
```
